namespace ProjectMgmt.Core.Ai;

/// <summary>
/// Final result of a completed AI generation request.
/// </summary>
public class AiCompletionResult
{
    /// <summary>
    /// Indicates whether the inference succeeded.
    /// </summary>
    public bool IsSuccess { get; set; } = true;

    /// <summary>
    /// Primary textual response generated by the model.
    /// </summary>
    public string? Content { get; set; }

    /// <summary>
    /// Reasoning or chain-of-thought output emitted by reasoning models.
    /// </summary>
    public string? Thought { get; set; }

    /// <summary>
    /// Tool calls requested by the model if function calling was triggered.
    /// </summary>
    public IReadOnlyList<AiToolCall>? ToolCalls { get; set; }

    /// <summary>
    /// Token usage metrics for the execution.
    /// </summary>
    public AiUsageInfo? Usage { get; set; }

    /// <summary>
    /// Finish reason reported by the model (e.g. "stop", "tool_calls", "length").
    /// </summary>
    public string? FinishReason { get; set; }

    /// <summary>
    /// Actual model name utilized for inference.
    /// </summary>
    public string? Model { get; set; }

    /// <summary>
    /// Error message if IsSuccess is false.
    /// </summary>
    public string? ErrorMessage { get; set; }

    public static AiCompletionResult Success(
        string content,
        string? thought = null,
        AiUsageInfo? usage = null,
        string? model = null,
        IReadOnlyList<AiToolCall>? toolCalls = null) =>
        new()
        {
            IsSuccess = true,
            Content = content,
            Thought = thought,
            Usage = usage,
            Model = model,
            ToolCalls = toolCalls,
            FinishReason = toolCalls is { Count: > 0 } ? "tool_calls" : "stop"
        };

    public static AiCompletionResult Failed(string errorMessage, string? model = null) =>
        new()
        {
            IsSuccess = false,
            ErrorMessage = errorMessage,
            Model = model,
            FinishReason = "error"
        };
}
